package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PreferredUsernameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property preferred username of user profile ")
  void test_preferred_username_v_o_builder() {
    Assertions.assertFalse(PreferredUsernameVO.nullValue().getPreferredUsername().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PreferredUsernameVO.tryFrom(null).getPreferredUsername().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        PreferredUsernameVO.from("one").getPreferredUsername().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> PreferredUsernameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PreferredUsernameVO.from("one").toString());
  }
}
